import json
import random
from pathlib import Path


# Puzzles come from the Lichess open puzzle database (CC0). puzzle_data.json is
# generated by scripts/build_puzzles; see the README before editing it by hand.
#
# Each rating category has 32 puzzles (16 forks, 16 pins) in three fixed sets:
#   warmup   5 forks + 5 pins   shown in the warm-up check
#   practice 6 forks + 6 pins   split at random between the two practice styles
#   final    5 forks + 5 pins   shown in the final check
PUZZLES = json.loads((Path(__file__).parent / "puzzle_data.json").read_text(encoding="utf-8"))

THEMES = ("Forks", "Pins")


def build_schedule(rating):
    """Return the puzzle ids for each phase for a participant with this rating.

    No puzzle appears twice. Each practice puzzle is assigned at random to
    question-based or answer-based practice, so across participants every
    practice puzzle is seen under both conditions.
    """
    band = {
        puzzle_id: puzzle
        for puzzle_id, puzzle in PUZZLES.items()
        if puzzle["rating_min"] <= rating <= puzzle["rating_max"]
    }
    if not band:
        raise ValueError(f"No puzzles are configured for rating {rating}.")

    def draw(set_name, theme):
        ids = [
            puzzle_id
            for puzzle_id, puzzle in band.items()
            if puzzle["set"] == set_name and puzzle["theme"] == theme
        ]
        random.shuffle(ids)
        return ids

    schedule = {"warmup": [], "practice_question": [], "practice_answer": [], "final": []}
    for theme in THEMES:
        schedule["warmup"] += draw("warmup", theme)
        schedule["final"] += draw("final", theme)
        practice = draw("practice", theme)
        half = len(practice) // 2
        schedule["practice_question"] += practice[:half]
        schedule["practice_answer"] += practice[half:]
    for puzzle_ids in schedule.values():
        random.shuffle(puzzle_ids)
    return schedule
